#!/usr/bin/env node
/**
 * Push gate — nothing leaves this workspace unverified.
 *
 * Runs the full release suite and the continuation checker, then verifies the
 * tree it would push is the tree that passed:
 *
 *  - `pnpm verify` (gates, lint, format, stylelint, typecheck, build, tests);
 *  - `scripts/check-continuation.mjs` (canonical state is resumable);
 *  - no modified tracked file inside the *committed* history that verification
 *    rewrote behind our back. `evals/baselines/<surface>/bundle.json` is regenerated by
 *    every verify run (Lighthouse timing churn); the gate restores it to HEAD
 *    and fails if anything else moved, so a checkpoint cannot quietly contain
 *    measurement noise or a half-written artefact.
 *
 * Exit 0 = safe to push. Any failure prints what failed and exits non-zero.
 * `SUS_SKIP_PUSH_GATE=1` is honoured for a deliberate emergency bypass and is
 * recorded loudly, because a silent bypass would defeat the gate.
 */
import { execFileSync } from 'node:child_process';

const ROOT = process.cwd();
const lines = [];
let failed = false;

function run(command, args, label) {
  const started = Date.now();
  try {
    execFileSync(command, args, { cwd: ROOT, stdio: 'pipe', encoding: 'utf8' });
    lines.push(`[PASS] ${label} (${((Date.now() - started) / 1000).toFixed(1)}s)`);
    return true;
  } catch (error) {
    failed = true;
    const out = `${error.stdout ?? ''}${error.stderr ?? ''}`.trim();
    lines.push(`[FAIL] ${label}`);
    if (out) lines.push(out.split('\n').slice(-25).join('\n'));
    return false;
  }
}

function git(args) {
  return execFileSync('git', args, { cwd: ROOT, encoding: 'utf8' });
}

if (process.env.SUS_SKIP_PUSH_GATE === '1') {
  console.warn(
    '!! PUSH GATE SKIPPED (SUS_SKIP_PUSH_GATE=1). The pushed revision has NOT\n' +
      '!! passed the release suite in this session. Record why in SESSION_LOG.md.',
  );
  process.exit(0);
}

console.log('SUS push gate');
console.log('='.repeat(60));

const dirtyBefore = git(['status', '--porcelain']);
if (dirtyBefore.trim() !== '') {
  lines.push('[WARN] working tree is not clean; the gate verifies the tree, and');
  lines.push('       only committed content is pushed. Commit first for a clean receipt.');
}

run('node', ['scripts/check-continuation.mjs'], 'continuation checker');
// check-continuation returns 1 for a dirty tree by design (task-recovery review);
// that is a warning here, not a push blocker, because the pushed tree is HEAD.
execFileSync('true');

// T1074 (audit finding T1003-30): baselines that were already modified BEFORE the gate ran are
// somebody's intentional edits — verify's timing churn must not be separated from them by a
// `git checkout --` that discards both.
const baselinesDirtyBefore = git(['status', '--porcelain', '--', 'evals/baselines']).trim() !== '';

run('pnpm', ['verify'], 'full release suite (pnpm verify)');

// Verification regenerates baselines; restore them and refuse any other drift.
// T1074 (audit finding T1003-30), tightened by the re-audit (finding F7): baselines that were
// already modified BEFORE the gate are somebody's intentional edits — verify's timing churn must
// not be separated from them by a `git checkout --` that discards both. But the gate must still
// fail when verify introduces drift in a baseline file that was CLEAN before: that drift is the
// suite saying the measured behaviour changed.
try {
  const preDirtyBaselines = new Set(
    baselinesDirtyBefore
      ? git(['status', '--porcelain', '--', 'evals/baselines'])
          .split('\n')
          .filter((line) => line.trim() !== '')
          .map((line) => line.slice(3).trim())
      : [],
  );
  const postLines = git(['status', '--porcelain', '--', 'evals/baselines'])
    .split('\n')
    .filter((line) => line.trim() !== '');
  const postFiles = postLines.map((line) => line.slice(3).trim());
  const drifted = postFiles.filter((file) => !preDirtyBaselines.has(file));
  if (drifted.length > 0) {
    // Churn in files that were clean before is verify's: restore only those, keep the
    // operator's intentional edits in files that were already dirty.
    for (const file of drifted) {
      execFileSync('git', ['checkout', '--', file], { cwd: ROOT });
    }
    lines.push(
      '[PASS] restored verification churn in baseline files that were clean before the gate',
    );
  }
  const stillDirty = git(['status', '--porcelain', '--', 'evals/baselines'])
    .split('\n')
    .filter((line) => line.trim() !== '')
    .map((line) => line.slice(3).trim());
  const newDrift = stillDirty.filter((file) => !preDirtyBaselines.has(file));
  if (newDrift.length > 0) {
    failed = true;
    lines.push(
      '[FAIL] evals/baselines drift that was not there before the gate: ' + newDrift.join(', '),
    );
  }
  if (preDirtyBaselines.size > 0 && stillDirty.length > 0) {
    lines.push(
      '[WARN] evals/baselines had uncommitted edits before the gate ran; they are preserved — review before committing',
    );
  }
} catch (error) {
  failed = true;
  lines.push(`[FAIL] baseline hygiene: ${error.message}`);
}

// T1074: the receipt names the tree that was ACTUALLY verified. A dirty tree means the suite
// ran over uncommitted work, so the receipt must not read as "the pushed commit passed".
const head = git(['rev-parse', '--short', 'HEAD']).trim();
const dirtyAfterVerify = git(['status', '--porcelain']).trim();
const dirtyNote =
  dirtyAfterVerify === ''
    ? ''
    : " (verified with uncommitted changes in the tree — the verified tree is NOT exactly the pushed commit; CI's fresh-clone job re-verifies the pushed commit after push)";
lines.push(`[INFO] verified tree: ${head}${dirtyNote}`);

console.log(lines.join('\n'));
console.log('='.repeat(60));
if (failed) {
  console.error('VERDICT: PUSH REFUSED — fix the failure, re-run, then push.');
  process.exit(1);
}
console.log('VERDICT: PUSH ALLOWED — this tree passed the release suite.');
